#include <iostream>
using std::cin;
using std::cout;

typedef long long int ll;


ll n, m, y;
ll a[21];
ll zeta[1LL << 21];

ll mygcd (ll l, ll r) {
	if (r == 0) return l;
	return mygcd(r, l % r);
}

int main (void) {
	cin >> n >> m >> y;
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
	}

	for (ll b = 0; !(b >> n); b++) {
		ll prod = 1;
		for (ll j = 0; j < n; j++) {
			if (b & (1LL << j)) {
				ll g = mygcd(prod, a[j]);
				if ((prod / g) > y / a[j]) {
					prod = y+1;
					break;
				} else {
					prod = (prod / g) * a[j];
				}
			}
		}
		zeta[b] = y / prod;
	}

	// zeta[01] <- mobius(zeta[*1])
	for (ll bi = 0; bi < n; bi++) {
		for (ll b = 0; !(b >> n); b++) {
			// [0] <- [*] - [1]
			if (!(b & (1LL << bi))) {
				zeta[b] = zeta[b] - zeta[b | (1LL << bi)];
			}
		}
	}

	ll ans[n+1];
	for (ll i = 0; i <= n; i++) {
		ans[i] = 0;
	}
	for (ll b = 0; !(b >> n); b++) {
		ll cnt = 0;
		for (ll j = 0; j < n; j++) {
			if (b & (1LL << j)) {
				cnt++;
			}
		}
		ans[cnt] += zeta[b];
	}

	cout << ans[m] << "\n";


	return 0;
}
